code='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    exterior = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background and (nr,nc) not in exterior:
                exterior.add((nr,nc)); q.append((nr,nc))
    out = [row[:] for row in grid]
    seen = set(exterior)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r,c) in seen:
                continue
            component = set()
            q.append((r,c)); seen.add((r,c))
            while q:
                cr, cc = q.popleft(); component.add((cr,cc))
                for nr, nc in ((cr-1,cc),(cr+1,cc),(cr,cc-1),(cr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            min_r = min(rr for rr, _ in component); max_r = max(rr for rr, _ in component)
            min_c = min(cc for _, cc in component); max_c = max(cc for _, cc in component)
            if len(component) == (max_r-min_r+1)*(max_c-min_c+1):
                for rr, cc in component:
                    out[rr][cc] = 4
    return out
'''
